source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    four = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    six = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [[0 if v == 6 else v for v in row] for row in grid]
    r0, r1 = min(r for r, c in four), max(r for r, c in four)
    c0, c1 = min(c for r, c in four), max(c for r, c in four)
    sr0, sr1 = min(r for r, c in six), max(r for r, c in six)
    sc0, sc1 = min(c for r, c in six), max(c for r, c in six)
    rows = [[c for r, c in six if r == rr] for rr in range(sr0, sr1 + 1)]
    widths = [len(cs) for cs in rows]
    if widths[0] == sc1 - sc0 + 1 and widths[-1] == 1:
        # Down-pointing marker: reflect the 4-object to the right.
        for r, c in four:
            cc = 2 * c1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif widths[-1] == sc1 - sc0 + 1 and widths[0] == 1:
        # Up-pointing marker: reflect the 4-object to the left.
        for r, c in four:
            cc = 2 * c0 - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        # Cross marker: reflect vertically; use its horizontal offset to select side.
        marker_x = sum(c for r, c in six) / len(six)
        source_x = sum(c for r, c in four) / len(four)
        if marker_x > source_x:
            for r, c in four:
                rr = 2 * r0 - 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
            for r, c in four:
                rr = 2 * r1 + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
    return out
'''
